// Scans src/content/**/*.mdx, validates each file's frontmatter, and writes a
// lightweight metadata index to src/content/.generated/index.ts.
//
// Why an index at all: listing pages, the sitemap and the prerenderer all need
// to know what content exists, but none of them need the article bodies. If
// they imported the MDX modules directly, rendering /insights would pull every
// article into one bundle. They read this cheap generated file instead, and
// only the article template ever loads a body — for the single route being
// rendered.
//
// Runs on `prebuild`, so an invalid draft fails the build rather than shipping.

import { readdirSync, readFileSync, writeFileSync, mkdirSync, statSync } from "node:fs";
import { join, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";
import matter from "gray-matter";
import { register } from "node:module";

const ROOT = fileURLToPath(new URL("..", import.meta.url));
const CONTENT_DIR = join(ROOT, "src", "content");
const OUT_DIR = join(CONTENT_DIR, ".generated");
const OUT_FILE = join(OUT_DIR, "index.ts");

/** Recursively collect .mdx files. */
const walk = (dir) => {
  let out = [];
  let entries;
  try {
    entries = readdirSync(dir, { withFileTypes: true });
  } catch {
    return out; // content dir not created yet
  }
  for (const entry of entries) {
    if (entry.name.startsWith(".")) continue; // skip .generated
    const full = join(dir, entry.name);
    if (entry.isDirectory()) out = out.concat(walk(full));
    else if (entry.name.endsWith(".mdx")) out.push(full);
  }
  return out;
};

/** Rough word count of the MDX body, excluding frontmatter and JSX tags. */
const countWords = (body) =>
  body
    .replace(/<[^>]+>/g, " ")
    .replace(/[#*_`>[\]()|-]/g, " ")
    .split(/\s+/)
    .filter(Boolean).length;

const main = async () => {
  // The schema is TypeScript, so load it through Vite's transform rather than
  // duplicating validation rules here — one source of truth for the contract.
  const { createServer } = await import("vite");
  const server = await createServer({
    server: { middlewareMode: true },
    appType: "custom",
    logLevel: "error",
  });

  let schemaModule;
  try {
    schemaModule = await server.ssrLoadModule("/src/content/schema.ts");
  } finally {
    // loaded below before closing
  }

  const { frontmatterSchema, contentPath } = schemaModule;

  const files = walk(CONTENT_DIR);
  const entries = [];
  const errors = [];

  for (const file of files) {
    const rel = relative(ROOT, file).split(sep).join("/");
    const raw = readFileSync(file, "utf-8");
    const { data, content } = matter(raw);

    const parsed = frontmatterSchema.safeParse(data);
    if (!parsed.success) {
      for (const issue of parsed.error.issues) {
        errors.push(`${rel}\n    ${issue.path.join(".") || "(root)"}: ${issue.message}`);
      }
      continue;
    }

    const fm = parsed.data;

    // The filename must match the slug, so a URL can always be traced back to
    // a file without consulting the index.
    const expected = `${fm.slug}.mdx`;
    if (!file.endsWith(expected)) {
      errors.push(`${rel}\n    filename must match slug — expected ${expected}`);
      continue;
    }

    const words = countWords(content);

    entries.push({
      ...fm,
      path: contentPath(fm.collection, fm.slug),
      file: `/${rel}`,
      wordCount: words,
      readingMinutes: Math.max(1, Math.round(words / 220)),
    });
  }

  await server.close();

  if (errors.length) {
    console.error(`\n✗ Content validation failed — ${errors.length} problem(s):\n`);
    for (const e of errors) console.error(`  • ${e}\n`);
    process.exit(1);
  }

  // Duplicate paths would make routing ambiguous.
  const seen = new Map();
  for (const e of entries) {
    if (seen.has(e.path)) {
      console.error(`\n✗ Duplicate path ${e.path} in ${e.file} and ${seen.get(e.path)}\n`);
      process.exit(1);
    }
    seen.set(e.path, e.file);
  }

  entries.sort((a, b) => b.publishedOn.localeCompare(a.publishedOn));

  const published = entries.filter((e) => e.status === "published");

  mkdirSync(OUT_DIR, { recursive: true });
  writeFileSync(
    OUT_FILE,
    `// GENERATED by scripts/build-content-index.mjs — do not edit.
// Regenerate with: npm run content:index

import type { ContentEntry } from "@/content/types";

/** Every content file, including drafts. Use for authoring tools only. */
export const allContent: ContentEntry[] = ${JSON.stringify(entries, null, 2)};

/** Published entries only — what routing, prerender and the sitemap consume. */
export const contentIndex: ContentEntry[] = allContent.filter(
  (entry) => entry.status === "published",
);
`,
    "utf-8",
  );

  const drafts = entries.length - published.length;
  console.log(
    `✓ content index: ${entries.length} file(s) — ${published.length} published, ${drafts} draft/review`,
  );
};

main().catch((error) => {
  console.error("✗ build-content-index failed:", error);
  process.exit(1);
});
